window.docContents[200].resolve({"/Basics/#Logical-Foundations--Basics___-Functional-Programming-in-Lean--General-Proofs-about-Natural-Numbers":{"contents":"A (slightly) more interesting theorem:\n\n\n\ntheorem add_id_example : ∀ n m : Nat,\n    n = m → n + n = m + m := by\n  intro n m\n  intro h\n  rewrite [h]\n  rfl\n\n\nRemove sorry and fill in the proof.theorem add_id_exercise : ∀ n m o : Nat,\n    n = m → m = o → n + m = m + o := by\n  sorry\n\n\n\n\n\n\n","context":"Logical Foundations\u0009Basics: Functional Programming in Lean","header":"1.3. General Proofs about Natural Numbers","id":"/Basics/#Logical-Foundations--Basics___-Functional-Programming-in-Lean--General-Proofs-about-Natural-Numbers"}});